// End-to-end parse of a Common App-style PDF (generated by tests/make_commonapp_pdf.py).
import { readFileSync } from "node:fs";
import { parseCommonApp, pdfToText } from "../src/lib/commonapp";

async function main() {
const pdfjs = await import("pdfjs-dist/legacy/build/pdf.mjs");
const file = process.argv[2] ?? "tests/fixtures/commonapp-sample.pdf";
const text = await pdfToText(pdfjs as never, new Uint8Array(readFileSync(file)));
const { profile: p, found, missing } = parseCommonApp(text);
const checks: [string, boolean][] = [
  ["name", p.name === "Priya Natarajan"],
  ["state", p.state === "IL"],
  ["high school", p.highSchool === "Walter Payton College Preparatory High School"],
  ["weighted GPA on 5-pt scale kept as weighted", p.gpaWeighted != null && Math.abs(p.gpaWeighted - 4.48) < 0.01 && p.gpaUnweighted == null],
  ["class rank 21/512 → top 4%", p.classRankPercent === 4],
  ["SAT 1500", p.sat === 1500],
  ["ACT 34", p.act === 34],
  ["5 AP/IB courses (honors excluded)", p.apCount === 5],
  ["2 honors", p.awards?.length === 2 && p.awards[0].level === "international" && p.awards[1].level === "state"],
  ["3 activities", p.activities?.length === 3],
  ["research org name", p.activities?.[0].name === "Northwestern University"],
  ["founder detected", !!p.activities?.[1].founder && !!p.activities?.[1].leadership],
  ["hours/weeks/years", p.activities?.[1].hoursPerWeek === 6 && p.activities?.[1].weeksPerYear === 36 && p.activities?.[1].years === 4],
  ["first-gen", p.firstGen === true],
  ["major", p.intendedMajor === "Biochemistry"],
  ["essay captured across pages", (p.personalStatement ?? "").startsWith("My grandmother kept") && (p.personalStatement ?? "").includes("ask what is really inside")],
  ["essay excludes prompt", !(p.personalStatement ?? "").includes("Share an essay")],
];
let fail = 0;
for (const [n, ok] of checks) { if (!ok) fail++; console.log(`${ok ? "✓" : "✗"} ${n}`); }
if (fail) { console.log(JSON.stringify(p, null, 1).slice(0, 3000)); console.log("---TEXT---\n" + text.slice(0, 2500)); }
console.log(`found: ${found.join(", ")} | missing: ${missing.join(", ")}`);
process.exit(fail ? 1 : 0);
}
main();
